package com.smartmart.order.entity; import com.smartmart.product.entity.Product; import com.smartmart.user.entity.User; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="cart_items",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","product_id"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class CartItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) private User user; @ManyToOne(fetch=FetchType.LAZY) private Product product; private Integer quantity;}
